/**
 * Boot-time checks on injected upstream credentials, shared by `buy gate` and
 * any host that mounts a gateway in-process.
 *
 * Both exist because settlement happens BEFORE the upstream call. A missing or
 * revoked credential does not fail a request — it charges the caller and then
 * hands them the upstream's 401, and x402 has no refund primitive.
 */
import { type PaywallConfig } from './config.js';
/** Credentials minted on demand, keyed like `injectHeaders` values (by variable name). */
export type HeaderProviders = Record<string, () => Promise<string>>;
/**
 * Resolve every `injectHeaders` env var across all proxy services, throwing on
 * any that is unset. The map is keyed by ENV VAR NAME, not header name: two
 * services may both inject `Authorization` from different variables, and a
 * header-keyed map could hold only one value for both of them.
 */
export declare function resolveInjectedHeaders(config: PaywallConfig, env?: Record<string, string | undefined>, providers?: HeaderProviders): Record<string, string>;
/**
 * Prove each injected credential is ACCEPTED before serving, not merely present.
 *
 * Every proxy upstream is probed with a GET of its origin carrying ONLY the
 * headers that service injects — one key per provider is the normal shape, and
 * a Google key sent to Alchemy proves nothing either way. Only a definitive
 * auth rejection is fatal. A 404 or 405 means the credential was accepted and
 * the path simply is not a route — that is a pass. A network failure is NOT a
 * pass and NOT a failure: it proves nothing about the credential, so it warns
 * and continues rather than letting a blip block a deploy.
 */
export declare function verifyUpstreamCredentials(config: PaywallConfig, resolvedHeaders: Record<string, string>, log: (line: string) => void, providers?: HeaderProviders): Promise<void>;
